class basic_ios {
    // Compiler adds Vptr pointing to Vtable
public:
    // Status flag management
    virtual bool good() const;

    // Streambuf interaction (must be implemented by derived classes)
    virtual std::streambuf* rdbuf() const = 0;

    // Essential for safe derived object destruction
    virtual ~basic_ios() = default;
};

void reset(basic_ios* stream) {
    // Runtime Vtable lookup determines which derived reset() is called
    stream->setstate(0);
}
